class Solution {
public:
    int countTriples(int n) {
        int count = 0;
        for (int a = 1; a <= n; a++) {
            for (int b = 1; b <= n; b++) {
                int c2 = a * a + b * b;
                int c = round(sqrt(c2));
                if (c <= n && c * c == c2) {
                    count++;
                }
            }
        }
        return count;
    }
};

class Solution {
    public int countTriples(int n) {
        int count = 0;
        for (int a = 1; a <= n; a++) {
            for (int b = 1; b <= n; b++) {
                int c2 = a * a + b * b;
                int c = (int)Math.round(Math.sqrt(c2));
                if (c <= n && c * c == c2) {
                    count++;
                }
            }
        }
        return count;
    }
}

var countTriples = function(n) {
  let count = 0;
  for (let a = 1; a <= n; a++) {
    for (let b = 1; b <= n; b++) {
      const c2 = a * a + b * b;
      const c = Math.round(Math.sqrt(c2));
      if (c <= n && c * c === c2) {
